  const openCreate = (startsAt = `${anchor}T09:00`, endsAt = `${anchor}T10:00`, initialType: CalendarEventType = 'event') => { setSelectedEventId(null); setEditorType(initialType); setEditorRange({ startsAt, endsAt }); setShowEditor(true); setFeedback(null) }; const openBlankContextMenu = (contextEvent: ReactMouseEvent<HTMLElement>, dayKey: string, minute = 9 * 60) => { contextEvent.preventDefault(); contextEvent.stopPropagation(); setContextMenu({ kind: 'blank', x: contextEvent.clientX, y: contextEvent.clientY, dayKey, minute }) }; const selectEvent = (event: CalendarEvent) => { setSelectedEventId(event.id); setShowEditor(false); setFeedback(null); if (event.readOnly) openSource(event) }; const openEdit = () => { if (selectedEvent && !selectedEvent.readOnly) setShowEditor(true) }; const openMove = () => { if (selectedEvent && !selectedEvent.readOnly) setMoveEvent(selectedEvent) }; const deleteEvent = (event = selectedEvent) => { if (!event) return; if (event.readOnly) { setFeedback('任务或项目截止日期为只读，请编辑来源对象。'); return }; if (window.confirm(`确认删除日程“${event.title}”吗？此操作不可撤销。`)) removeMutation.mutate(event) }
